// ---------- Saved copies (shared by the widget and the app) ----------
function docPath(name) {
  const fm = FileManager.local();
  return fm.joinPath(fm.documentsDirectory(), name);
}
function readJSON(name) {
  const fm = FileManager.local();
  const p = docPath(name);
  for (const q of [p, p + ".tmp"]) {
    try {
      if (fm.fileExists(q)) return JSON.parse(fm.readString(q));
    } catch (e) {}
  }
  return null;
}
function writeJSON(name, obj) {
  const fm = FileManager.local();
  const p = docPath(name);
  const tmp = p + ".tmp";
  try {
    fm.writeString(tmp, JSON.stringify(obj));
    if (fm.fileExists(p)) fm.remove(p);
    fm.move(tmp, p);
  } catch (e) {
    try { fm.writeString(p, JSON.stringify(obj)); } catch (e2) {}
  }
}
const sleep = (ms) => new Promise((r) => Timer.schedule(ms, false, r));
const daysSince = (iso) => (iso ? (Date.now() - new Date(iso).getTime()) / DAY_MS : Infinity);
const pad2 = (n) => String(n).padStart(2, "0");
const irsCode = (yy) => pad2(yy % 100) + pad2((yy + 1) % 100);
const irsLabel = (code) => `20${code.slice(0, 2)}–${code.slice(2)}`;
function headerOf(resp, name) {
  const h = (resp && resp.headers) || {};
  const k = Object.keys(h).find((x) => x.toLowerCase() === name.toLowerCase());
  return k ? String(h[k]) : null;
}
// "Austin-Round Rock-San Marcos, TX" -> "Austin, TX"
function shortName(full) {
  const parts = String(full).split(",");
  const city = parts[0].split("-")[0].split("/")[0].trim().replace(/^Urban /, "");
  const st = (parts[1] || "").trim().split("-")[0].slice(0, 2);
  return st ? `${city}, ${st}` : city;
}
const cityKey = (full) => shortName(full).replace(", ", "|");

// ---------- Downloads ----------
async function getData(url, timeout) {
  const req = new Request(url);
  req.timeoutInterval = timeout || 60;
  req.headers = { "User-Agent": UA };
  let data = null;
  try {
    data = await req.load();
  } catch (e) {
    return { status: 0, error: String(e.message || e) };
  }
  const r = req.response || {};
  return { status: r.statusCode || 0, data, lm: headerOf(r, "Last-Modified"), type: headerOf(r, "Content-Type") || "" };
}
async function getText(url, timeout) {
  const req = new Request(url);
  req.timeoutInterval = timeout || 30;
  req.headers = { "User-Agent": UA };
  try {
    const text = await req.loadString();
    return { status: (req.response && req.response.statusCode) || 0, text };
  } catch (e) {
    return { status: 0, text: null, error: String(e.message || e) };
  }
}
async function headInfo(url, timeout) {
  const req = new Request(url);
  req.method = "HEAD";
  req.timeoutInterval = timeout || 20;
  req.headers = { "User-Agent": UA };
  try {
    await req.load();
    const r = req.response || {};
    return { status: r.statusCode || 0, lm: headerOf(r, "Last-Modified"), type: headerOf(r, "Content-Type") || "" };
  } catch (e) {
    return { status: 0 };
  }
}

// ---------- Reading big files in a hidden web page ----------
// The page has fast text decoding and the unzipper. Census files are Latin-1
// in some years and UTF-8 in others; both are handled. Plain browser JS.
function pageLib() {
  window.__bytes = function (b64) {
    var bin = atob(b64), u = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
    return u;
  };
  window.__text = function (u) {
    var t;
    try { t = new TextDecoder("utf-8", { fatal: true }).decode(u); } catch (e) { t = new TextDecoder("windows-1252").decode(u); }
    return t.charCodeAt(0) === 0xFEFF ? t.slice(1) : t;
  };
  window.__split = function (line) {
    if (line.indexOf('"') < 0) return line.split(",");
    var out = [], cur = "", q = false;
    for (var i = 0; i < line.length; i++) {
      var ch = line[i];
      if (q) { if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else q = false; } else cur += ch; }
      else if (ch === '"') q = true;
      else if (ch === ",") { out.push(cur); cur = ""; }
      else cur += ch;
    }
    out.push(cur);
    return out;
  };
  window.__unzip = async function (buf, want) {
    var dv = new DataView(buf.buffer), dec = new TextDecoder(), eocd = -1;
    for (var e = buf.length - 22; e >= Math.max(0, buf.length - 70000); e--) if (dv.getUint32(e, true) === 0x06054b50) { eocd = e; break; }
    if (eocd < 0) throw new Error("not a zip file");
    var count = dv.getUint16(eocd + 10, true), p = dv.getUint32(eocd + 16, true), entries = [];
    for (var k = 0; k < count; k++) {
      if (dv.getUint32(p, true) !== 0x02014b50) break;
      var nlen = dv.getUint16(p + 28, true), xlen = dv.getUint16(p + 30, true), clen = dv.getUint16(p + 32, true);
      entries.push({ name: dec.decode(buf.subarray(p + 46, p + 46 + nlen)), method: dv.getUint16(p + 10, true),
        csize: dv.getUint32(p + 20, true), usize: dv.getUint32(p + 24, true), off: dv.getUint32(p + 42, true) });
      p += 46 + nlen + xlen + clen;
    }
    var hits = entries.filter(function (x) { return want.test(x.name) && !/__MACOSX/.test(x.name); });
    if (!hits.length) throw new Error("zip has no matching file (" + entries.map(function (x) { return x.name; }).join(", ") + ")");
    hits.sort(function (a, b) { return b.usize - a.usize; });
    var en = hits[0], start = en.off + 30 + dv.getUint16(en.off + 26, true) + dv.getUint16(en.off + 28, true);
    var stream = new Blob([buf.subarray(start, start + en.csize)]).stream();
    if (en.method === 8) stream = stream.pipeThrough(new DecompressionStream("deflate-raw"));
    else if (en.method !== 0) throw new Error("unsupported zip compression " + en.method);
    var out = new Uint8Array(await new Response(stream).arrayBuffer());
    return window.__text(out);
  };
}

// Census population estimates file (metros, micros and their counties)
async function censusParse(b64) {
  var text = __text(__bytes(b64));
  b64 = null;
  var lines = text.split(/\r?\n/);
  var head = __split(lines[0]).map(function (h) { return h.trim().toUpperCase(); });
  var at = function (n) { return head.indexOf(n); };
  var iC = at("CBSA"), iM = at("MDIV"), iS = at("STCOU"), iN = at("NAME"), iL = at("LSAD");
  if (iC < 0 || iN < 0) throw new Error("Census file has no CBSA / NAME columns (" + head.slice(0, 8).join(", ") + ")");
  var base = null, cols = {};
  var KEY = { POPESTIMATE: "pop", NPOPCHG: "chg", NATURALCHG: "nat", NATURALINC: "nat", INTERNATIONALMIG: "intl", DOMESTICMIG: "dom" };
  head.forEach(function (h, i) {
    var b = h.match(/^ESTIMATESBASE(\d{4})$/);
    if (b) base = +b[1];
    var m = h.match(/^([A-Z]+?)_?(\d{4})$/);
    if (m && KEY[m[1]]) { var k = KEY[m[1]]; (cols[k] = cols[k] || {})[+m[2]] = i; }
  });
  if (!cols.dom) throw new Error("Census file has no DOMESTICMIG columns");
  // the base year's column covers only April to July, so it's left out
  var years = Object.keys(cols.dom).map(Number).filter(function (y) { return base == null || y > base; }).sort(function (a, b) { return a - b; });
  var popYears = Object.keys(cols.pop || {}).map(Number).sort(function (a, b) { return a - b; });
  var f = null;
  var series = function (k, ys) {
    var c = cols[k] || {};
    return ys.map(function (y) { var i = c[y]; if (i == null) return null; var v = parseFloat(f[i]); return isFinite(v) ? v : null; });
  };
  var metros = [], counties = {}, micros = {};
  for (var r = 1; r < lines.length; r++) {
    if (!lines[r]) continue;
    f = __split(lines[r]);
    var code = String(f[iC] || "").trim();
    if (!/^\d{5}$/.test(code)) continue;
    var lsad = iL >= 0 ? String(f[iL] || "").toLowerCase() : "";
    var mdiv = iM >= 0 ? String(f[iM] || "").trim() : "";
    var stc = iS >= 0 ? String(f[iS] || "").trim() : "";
    if (lsad.indexOf("county") >= 0 || (iL < 0 && /^\d{4,5}$/.test(stc))) {
      if (/^\d{4,5}$/.test(stc)) counties[("0" + stc).slice(-5)] = code;
      continue;
    }
    if (mdiv || lsad.indexOf("division") >= 0) continue;
    var type = lsad.indexOf("micropolitan") >= 0 ? "m" : lsad.indexOf("metropolitan") >= 0 ? "M" : null;
    if (!type) continue;
    var name = String(f[iN]).trim();
    if (type === "m") { var pp = series("pop", popYears); micros[code] = { n: name, pop: pp[pp.length - 1] }; continue; }
    metros.push({ c: code, n: name, pop: series("pop", popYears), dom: series("dom", years), intl: series("intl", years), nat: series("nat", years), chg: series("chg", years) });
  }
  return { base: base, years: years, popYears: popYears, metros: metros, micros: micros, counties: counties };
}

// Census Gazetteer (zipped, tab-separated): each CBSA's interior point
async function gazParse(b64) {
  var text = await __unzip(__bytes(b64), /\.txt$/i);
  var lines = text.split(/\r?\n/), head = lines[0].split("\t").map(function (s) { return s.trim().toUpperCase(); });
  var iG = head.indexOf("GEOID");
  if (iG < 0) iG = head.indexOf("CBSAFP");
  var iLa = head.indexOf("INTPTLAT"), iLo = head.indexOf("INTPTLONG");
  if (iLo < 0) iLo = head.indexOf("INTPTLON");
  if (iG < 0 || iLa < 0 || iLo < 0) throw new Error("Gazetteer layout not recognized (" + head.join(", ") + ")");
  var out = {};
  for (var r = 1; r < lines.length; r++) {
    var f = lines[r].split("\t");
    var g = String(f[iG] || "").trim(), la = parseFloat(f[iLa]), lo = parseFloat(f[iLo]);
    if (/^\d{5}$/.test(g) && isFinite(la) && isFinite(lo)) out[g] = [Math.round(la * 1000) / 1000, Math.round(lo * 1000) / 1000];
  }
  return out;
}

// IRS county-to-county file, rolled up to metros. Pairs come from the inflow
// file; each file's "total U.S." rows give a county's total moves in or out.
async function irsParse(b64, x) {
  var text = __text(__bytes(b64));
  b64 = null;
  var nl = text.indexOf("\n");
  var head = __split(text.slice(0, nl).replace("\r", "")).map(function (h) { return h.trim().toLowerCase(); });
  var find = function (test) { for (var i = 0; i < head.length; i++) if (test(head[i])) return i; return -1; };
  var oS = find(function (h) { return h === "y1_statefips" || /state_code_orig/.test(h); });
  var oC = find(function (h) { return h === "y1_countyfips" || /county_code_orig/.test(h); });
  var dS = find(function (h) { return h === "y2_statefips" || /state_code_dest/.test(h); });
  var dC = find(function (h) { return h === "y2_countyfips" || /county_code_dest/.test(h); });
  var i1 = find(function (h) { return h === "n1" || /return_num/.test(h); });
  var i2 = find(function (h) { return h === "n2" || /exmpt_num|indiv/.test(h); });
  var iA = find(function (h) { return h === "agi" || /aggr_agi/.test(h); });
  if (oS < 0 || oC < 0 || dS < 0 || dC < 0 || i1 < 0 || i2 < 0 || iA < 0) throw new Error("IRS file layout not recognized (" + head.join(",") + ")");
  var cw = x.cw, ct = x.ct || {}, M = x.metros, inflow = x.kind === "in";
  var cb = function (st, co) { var k = ("0" + st).slice(-2) + ("00" + co).slice(-3); return cw[k] || ct[k] || "S" + ("0" + st).slice(-2); };
  var add = function (o, k, a, b, c) { var r = o[k] || (o[k] = [0, 0, 0]); r[0] += a; r[1] += b; r[2] += c; };
  var pairs = {}, tot = {}, within = {}, rows = 0, pos = nl + 1;
  while (pos < text.length) {
    var end = text.indexOf("\n", pos);
    if (end < 0) end = text.length;
    var line = text.slice(pos, end);
    pos = end + 1;
    if (line.length < 5) continue;
    var f = line.indexOf('"') < 0 ? line.split(",") : __split(line);
    var os = parseInt(f[oS], 10), oc = parseInt(f[oC], 10), ds = parseInt(f[dS], 10), dc = parseInt(f[dC], 10);
    if (!(os >= 0) || !(ds >= 0)) continue;
    rows++;
    var n1 = parseFloat(f[i1]), n2 = parseFloat(f[i2]), agi = parseFloat(f[iA]) || 0;
    if (!(n1 >= 0) || !(n2 >= 0)) continue; // suppressed
    if (inflow && os === 97 && oc === 0 && ds >= 1 && ds <= 56) { var D0 = cb(ds, dc); if (M[D0]) add(tot, D0, n1, n2, agi); continue; }
    if (!inflow && ds === 97 && dc === 0 && os >= 1 && os <= 56) { var O0 = cb(os, oc); if (M[O0]) add(tot, O0, n1, n2, agi); continue; }
    if (!inflow || os < 1 || os > 56 || ds < 1 || ds > 56 || (os === ds && oc === dc)) continue;
    var O = cb(os, oc), D = cb(ds, dc);
    if (O === D) { if (M[O]) add(within, O, n1, n2, agi); continue; }
    if (M[O] || M[D]) add(pairs, D + "|" + O, n1, n2, agi);
  }
  return { rows: rows, pairs: pairs, tot: tot, within: within };
}

async function runInPage(fn, b64, extra, seconds) {
  const wv = updWV(new WebView());
  await wv.loadHTML(...updArgs("<!DOCTYPE html><html><body></body></html>"));
  const js = "(" + pageLib.toString() + ")();window.__out='';(" + fn.toString() + ")(" + JSON.stringify(b64) + "," + JSON.stringify(extra == null ? null : extra) + ")" +
    ".then(function(r){window.__out=JSON.stringify({ok:true,data:r});})" +
    ".catch(function(e){window.__out=JSON.stringify({ok:false,error:String(e&&e.message||e)});});0;";
  await wv.evaluateJavaScript(js, false);
  const t0 = Date.now();
  while (Date.now() - t0 < (seconds || 90) * 1000) {
    await sleep(250);
    const out = await wv.evaluateJavaScript("window.__out || ''", false);
    if (out) {
      const o = JSON.parse(out);
      if (!o.ok) throw new Error(o.error);
      return o.data;
    }
  }
  throw new Error("timed out reading the file");
}

// ---------- Census: find, fetch, stitch ----------
// Census keeps one folder per vintage (2020-2024, 2020-2025, ...). The newest
// folder's metro file is the current one; the folder ending where the current
// decade starts (2010-2020) holds the history.
async function discoverCensus(timeout) {
  const r = await getText(CENSUS_ROOT, timeout || 30);
  if (r.status !== 200 || !r.text) return null;
  const folders = [...r.text.matchAll(/href="((\d{4})-(\d{4}))\/"/g)].map((m) => ({ name: m[1], a: +m[2], b: +m[3] }));
  folders.sort((x, y) => y.b - x.b || y.a - x.a);
  for (const f of folders.slice(0, 3)) {
    const dir = `${CENSUS_ROOT}${f.name}/metro/totals/`;
    const l = await getText(dir, timeout || 30);
    if (l.status !== 200 || !l.text) continue;
    const files = [...l.text.matchAll(/href="(cbsa-est(\d{4})-alldata\.csv)"/gi)].map((m) => ({ file: m[1], v: +m[2] })).sort((a, b) => b.v - a.v);
    if (!files.length) continue;
    const hist = folders.find((h) => h.b === f.a && h.a < f.a);
    return { vintage: files[0].v, url: dir + files[0].file, start: f.a, histDir: hist ? `${CENSUS_ROOT}${hist.name}/metro/totals/` : null };
  }
  return null;
}
async function fetchCensus(url, seconds) {
  const r = await getData(url, 90);
  if (r.status !== 200 || !r.data) throw new Error(`Census answered ${r.status || r.error || "nothing"} for ${url.split("/").pop()}`);
  if (/html/i.test(r.type)) throw new Error("Census sent a web page instead of the data file");
  const p = await runInPage(censusParse, r.data.toBase64String(), null, seconds);
  if (!p.metros || p.metros.length < 300 || !p.years.length) throw new Error(`Census file looks incomplete (${(p.metros || []).length} metros)`);
  return { ...p, lm: r.lm };
}
async function fetchHistory(disc, seconds) {
  const urls = [];
  if (disc && disc.histDir) {
    const l = await getText(disc.histDir, 30);
    if (l.status === 200 && l.text) {
      const files = [...l.text.matchAll(/href="(cbsa-est(\d{4})-alldata\.csv)"/gi)].map((m) => ({ file: m[1], v: +m[2] })).sort((a, b) => b.v - a.v);
      if (files.length) urls.push(disc.histDir + files[0].file);
    }
  }
  for (const u of KNOWN_HISTORY) if (!urls.includes(u)) urls.push(u);
  for (const u of urls) {
    try {
      const h = await fetchCensus(u, seconds);
      return { ...h, url: u };
    } catch (e) {}
  }
  return null;
}
// Put the earlier decade in front of the current file, matched by CBSA code
// (or by principal city when a code changed). Each file keeps its own metro
// definitions; the 2010s years aren't revised to the 2020 Census.
function stitch(cur, hist) {
  const firstY = cur.years[0], firstP = cur.popYears[0];
  const hy = hist ? hist.years.filter((y) => y < firstY) : [];
  const hp = hist ? hist.popYears.filter((y) => y < firstP) : [];
  const byCode = {}, byKey = {};
  if (hist) for (const m of hist.metros) { byCode[m.c] = m; byKey[cityKey(m.n)] = m; }
  const pick = (h, k, ys, src) => ys.map((y) => { const i = src.indexOf(y); return h && i >= 0 ? h[k][i] : null; });
  const metros = cur.metros.map((m) => {
    const h = byCode[m.c] || byKey[cityKey(m.n)] || null;
    return {
      c: m.c, n: m.n, h: h ? (h.c === m.c ? 1 : 2) : 0,
      pop: pick(h, "pop", hp, hist ? hist.popYears : []).concat(m.pop),
      dom: pick(h, "dom", hy, hist ? hist.years : []).concat(m.dom),
      intl: pick(h, "intl", hy, hist ? hist.years : []).concat(m.intl),
      nat: pick(h, "nat", hy, hist ? hist.years : []).concat(m.nat),
      chg: pick(h, "chg", hy, hist ? hist.years : []).concat(m.chg),
    };
  });
  return { years: hy.concat(cur.years), popYears: hp.concat(cur.popYears), metros, splitYear: hy.length ? firstY : null };
}
function crosswalkSig(counties) {
  const keys = Object.keys(counties).sort();
  let h = 0;
  for (const k of keys) {
    const s = k + counties[k];
    for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0;
  }
  return `${keys.length}-${(h >>> 0).toString(36)}`;
}
async function fetchCoords(seconds) {
  const y0 = new Date().getFullYear();
  for (let y = y0; y >= 2023; y--) {
    const r = await getData(GAZ_URL(y), 60);
    if (r.status !== 200 || !r.data || /html/i.test(r.type)) continue;
    try {
      const c = await runInPage(gazParse, r.data.toBase64String(), null, seconds);
      if (Object.keys(c).length > 300) return { coords: c, year: y };
    } catch (e) {}
  }
  return null;
}
function coordOf(cen, code, name) {
  return (cen.coords && cen.coords[code]) || METRO_COORDS_FALLBACK[cityKey(name)] || null;
}

// Weekly: is there a newer vintage, or a revised copy of this one?
async function refreshCensus(cen, force, seconds) {
  if (cen && cen.metros && !force && daysSince(cen.checked) < CHECK_DAYS) return cen;
  let disc = null;
  try { disc = await discoverCensus(); } catch (e) {}
  let target = null;
  if (!cen || !cen.metros) target = disc || KNOWN_CURRENT;
  else if (disc && disc.vintage > cen.vintage) target = disc;
  else if (disc && disc.url === cen.url) {
    const h = await headInfo(cen.url);
    if (h.status === 200 && h.lm && cen.lm && h.lm !== cen.lm) target = disc; // revised in place
  } else if (!disc) {
    const v = cen.vintage + 1, guess = `${CENSUS_ROOT}2020-${v}/metro/totals/cbsa-est${v}-alldata.csv`;
    const h = await headInfo(guess);
    if (h.status === 200 && !/html/i.test(h.type)) target = { vintage: v, url: guess, start: 2020, histDir: `${CENSUS_ROOT}2010-2020/metro/totals/` };
  }
  if (!target) {
    const out = { ...cen, checked: new Date().toISOString(), error: disc ? null : "Census site unreachable; using the saved copy" };
    writeJSON(CENSUS_FILE, out);
    return out;
  }
  const cur = await fetchCensus(target.url, seconds);
  const vintage = target.vintage || Math.max(...cur.years);
  // history: reuse the saved one unless the decade changed
  let hist = cen && cen.hist && cen.hist.start === (target.start || 2020) ? cen.hist : null;
  if (!hist) {
    const h = await fetchHistory(target, seconds);
    hist = h ? { start: target.start || 2020, url: h.url, years: h.years, popYears: h.popYears, metros: h.metros.map((m) => ({ c: m.c, n: m.n, pop: m.pop, dom: m.dom, intl: m.intl, nat: m.nat, chg: m.chg })) } : null;
  }
  const st = stitch(cur, hist);
  let coords = cen && cen.coords;
  const covered = (c) => c && st.metros.filter((m) => c[m.c]).length / st.metros.length;
  if (!coords || covered(coords) < 0.95) {
    const g = await fetchCoords(seconds);
    if (g && covered(g.coords) >= (covered(coords) || 0)) coords = g.coords;
  }
  const out = {
    vintage, url: target.url, lm: cur.lm, checked: new Date().toISOString(), fetched: new Date().toISOString(),
    years: st.years, popYears: st.popYears, splitYear: st.splitYear, metros: st.metros,
    micros: cur.micros, counties: cur.counties, sig: crosswalkSig(cur.counties),
    hist, coords: coords || {}, histMissing: !hist, error: null,
  };
  writeJSON(CENSUS_FILE, out);
  writeFace(out, null);
  return out;
}

// ---------- IRS flows: newest first, then back-fill older years ----------
function metroSet(cen) {
  const s = {};
  for (const m of cen.metros) s[m.c] = 1;
  return s;
}
function buildIrsYear(pin, pout, M) {
  const by = {};
  for (const key of Object.keys(pin.pairs)) {
    const [D, O] = key.split("|");
    const v = pin.pairs[key];
    if (M[D]) { const p = (by[D] = by[D] || {}); const r = (p[O] = p[O] || [0, 0, 0, 0, 0, 0]); r[0] += v[0]; r[1] += v[1]; r[2] += v[2]; }
    if (M[O]) { const p = (by[O] = by[O] || {}); const r = (p[D] = p[D] || [0, 0, 0, 0, 0, 0]); r[3] += v[0]; r[4] += v[1]; r[5] += v[2]; }
  }
  const out = {};
  for (const m of Object.keys(M)) {
    const ti = pin.tot[m], to = pout ? pout.tot[m] : null, w = pin.within[m] || [0, 0, 0];
    const t = [
      ti ? ti[0] - w[0] : null, ti ? ti[1] - w[1] : null, ti ? ti[2] - w[2] : null,
      to ? to[0] - w[0] : null, to ? to[1] - w[1] : null, to ? to[2] - w[2] : null,
    ].map((v) => (v == null ? null : Math.round(v)));
    const parts = Object.entries(by[m] || {});
    const keep = new Set();
    const top = (fn) => parts.slice().sort((a, b) => fn(b[1]) - fn(a[1])).slice(0, TOP_PARTNERS).forEach((p) => keep.add(p[0]));
    top((r) => r[1]);
    top((r) => r[4]);
    top((r) => Math.abs(r[1] - r[4]));
    out[m] = { t, p: parts.filter((p) => keep.has(p[0])).map(([c, r]) => [c].concat(r.map(Math.round))) };
  }
  return out;
}
async function processIrsYear(code, cen, seconds) {
  const a = await getData(IRS_URL("inflow", code), 150);
  if (a.status === 404 || (a.status === 200 && /html/i.test(a.type))) return { missing: true };
  if (a.status !== 200 || !a.data) throw new Error(`IRS answered ${a.status || a.error || "nothing"}`);
  const x = { cw: cen.counties, ct: CT_OLD_COUNTIES, metros: metroSet(cen) };
  const pin = await runInPage(irsParse, a.data.toBase64String(), { ...x, kind: "in" }, seconds);
  if (pin.rows < 5000) return { missing: true };
  let pout = null;
  const b = await getData(IRS_URL("outflow", code), 150);
  if (b.status === 200 && b.data && !/html/i.test(b.type)) {
    try { pout = await runInPage(irsParse, b.data.toBase64String(), { ...x, kind: "out" }, seconds); } catch (e) {}
  }
  return { m: buildIrsYear(pin, pout, x.metros), out: !!pout };
}
// What to fetch next: a newer year (checked weekly), then years built on an
// older metro map, then older years not yet loaded
function irsNext(irs, cen) {
  const done = Object.keys(irs.years || {});
  const latest = done.reduce((mx, c) => Math.max(mx, +c.slice(0, 2)), IRS_KNOWN_LATEST);
  const missOk = (c) => daysSince((irs.missing || {})[c]) > MISSING_RETRY_DAYS;
  const nowYY = new Date().getFullYear() % 100;
  if (daysSince(irs.probed) >= CHECK_DAYS) {
    for (let yy = latest + 1; yy <= Math.min(latest + 2, nowYY - 1); yy++) {
      const c = irsCode(yy);
      if (!irs.years[c]) return { code: c, probe: true };
    }
  }
  const stale = done.filter((c) => irs.years[c].sig !== cen.sig).sort().reverse();
  if (stale.length) return { code: stale[0] };
  for (let yy = latest; yy >= IRS_FIRST; yy--) {
    const c = irsCode(yy);
    if (!irs.years[c] && missOk(c)) return { code: c };
  }
  return null;
}
async function irsStep(irs, cen, seconds) {
  const next = irsNext(irs, cen);
  if (!next) return { irs, done: true };
  let r;
  try {
    r = await processIrsYear(next.code, cen, seconds);
  } catch (e) {
    irs.error = `IRS ${irsLabel(next.code)}: ${e.message || e}`;
    if (next.probe) irs.probed = new Date().toISOString();
    writeJSON(IRS_FILE, irs);
    return { irs, done: true, error: irs.error };
  }
  if (r.missing) {
    irs.missing = irs.missing || {};
    irs.missing[next.code] = new Date().toISOString();
    if (next.probe) irs.probed = new Date().toISOString();
  } else {
    irs.years[next.code] = { sig: cen.sig, fetched: new Date().toISOString(), out: r.out, m: r.m };
    if (irs.missing) delete irs.missing[next.code];
    irs.error = null;
    if (next.probe) irs.probed = new Date().toISOString();
  }
  writeJSON(IRS_FILE, irs);
  return { irs, code: next.code, loaded: !r.missing };
}
function irsFresh() {
  const s = readJSON(IRS_FILE);
  return s && s.years ? s : { years: {}, missing: {} };
}

// ---------- Widget summary ----------
function popAt(cen, m, year) {
  const i = cen.popYears.indexOf(year);
  return i >= 0 ? m.pop[i] : null;
}
function faceRows(cen, yi, rate) {
  const y = cen.years[yi];
  const rows = [];
  for (const m of cen.metros) {
    const v = m.dom[yi];
    if (v == null) continue;
    if (rate) {
      const p0 = popAt(cen, m, y - 1), p1 = popAt(cen, m, y);
      if (!(p1 >= BIG_METRO) || !p0) continue;
      rows.push([shortName(m.n), Math.round((v / p0) * 10000) / 10]);
    } else rows.push([shortName(m.n), v]);
  }
  rows.sort((a, b) => b[1] - a[1]);
  return { up: rows.slice(0, 3), down: rows.slice(-3).reverse() };
}
function writeFace(cen, pending) {
  const yi = cen.years.length - 1;
  const old = readJSON(FACE_FILE) || {};
  const face = {
    year: cen.years[yi], vintage: cen.vintage, checked: cen.checked,
    count: faceRows(cen, yi, false), rate: faceRows(cen, yi, true),
    probed: old.probed || null, pending: pending === undefined ? old.pending || null : pending,
  };
  writeJSON(FACE_FILE, face);
  return face;
}
// The widget can't read the big files, but it can notice that new ones are
// out (two small directory listings) and say so on its face
async function widgetProbe(face) {
  if (!face || daysSince(face.probed) < CHECK_DAYS) return face;
  // mark the check first, so a slow census.gov costs one refresh a week at most
  writeJSON(FACE_FILE, { ...face, probed: new Date().toISOString() });
  let pending = face.pending || null;
  try {
    const d = await discoverCensus(6);
    if (d && d.vintage > face.vintage) pending = `Census ${d.vintage}`;
  } catch (e) {}
  if (!pending) {
    const irs = readJSON(IRS_FILE);
    const latest = irs && irs.years ? Object.keys(irs.years).reduce((mx, c) => Math.max(mx, +c.slice(0, 2)), 0) : 0;
    if (latest) {
      const h = await headInfo(IRS_URL("inflow", irsCode(latest + 1)), 6);
      if (h.status === 200 && !/html/i.test(h.type)) pending = `IRS ${irsLabel(irsCode(latest + 1))}`;
    }
  }
  const out = { ...face, probed: new Date().toISOString(), pending };
  writeJSON(FACE_FILE, out);
  return out;
}

// ---------- Widget ----------
function drawText(ctx, str, rect, font, hex, align) {
  ctx.setFont(font);
  ctx.setTextColor(new Color(hex));
  if (align === "right") ctx.setTextAlignedRight();
  else if (align === "center") ctx.setTextAlignedCenter();
  else ctx.setTextAlignedLeft();
  ctx.drawTextInRect(str, rect);
}
function newCanvas(W, H) {
  const ctx = new DrawContext();
  ctx.size = new Size(W, H);
  ctx.opaque = true;
  ctx.respectScreenScale = true;
  const top = [0x2c, 0x2c, 0x2e];
  const bottom = [0x1c, 0x1c, 0x1e];
  for (let i = 0; i < 34; i++) {
    const f = i / 33;
    const hex = "#" + top.map((c, j) => Math.round(c + (bottom[j] - c) * f).toString(16).padStart(2, "0")).join("");
    ctx.setFillColor(new Color(hex));
    ctx.fillRect(new Rect(0, (H * i) / 34, W, H / 34 + 1));
  }
  return ctx;
}
function kFmt(v) {
  const a = Math.abs(v), s = v < 0 ? "−" : "+";
  if (a >= 100000) return s + Math.round(a / 1000) + "k";
  if (a >= 1000) return s + (a / 1000).toFixed(1) + "k";
  return s + Math.round(a);
}
function rateFmt(v) {
  return (v < 0 ? "−" : "+") + Math.abs(v).toFixed(1);
}
function widgetMode() {
  return /rate|1000|per/i.test(String(args.widgetParameter || "")) ? "rate" : "count";
}
function fit(name, max) {
  const s = name.split(",")[0];
  return s.length > max ? s.slice(0, max - 1) + "…" : s;
}
function smallImage(face, mode) {
  const W = 170;
  const ctx = newCanvas(W, W);
  drawText(ctx, "Migration", new Rect(14, 11, 90, 17), Font.boldSystemFont(13), "#FFFFFF", "left");
  const yy = String(face.year);
  drawText(ctx, `’${pad2((face.year - 1) % 100)}–’${yy.slice(2)}`, new Rect(W - 64, 13, 50, 14), Font.mediumSystemFont(10), GRAY, "right");
  const rows = mode === "rate" ? face.rate : face.count;
  const fmt = mode === "rate" ? rateFmt : kFmt;
  const block = (label, list, y, hex) => {
    drawText(ctx, label, new Rect(14, y, 142, 13), Font.semiboldSystemFont(9.5), hex, "left");
    (list || []).forEach((r, i) => {
      const ry = y + 13 + i * 15;
      drawText(ctx, fit(r[0], 15), new Rect(14, ry, 96, 15), Font.semiboldSystemFont(11.5), "#FFFFFF", "left");
      drawText(ctx, fmt(r[1]), new Rect(96, ry, 60, 15), Font.boldSystemFont(11.5), hex, "right");
    });
  };
  block("GAINING", rows.up, 31, GREEN);
  block("LOSING", rows.down, 91, RED);
  if (face.pending) {
    drawText(ctx, "New data · tap to load", new Rect(14, 151, 142, 12), Font.semiboldSystemFont(9), AMBER, "left");
  } else {
    const foot = mode === "rate" ? "Per 1,000 residents · 1M+" : "Net domestic movers";
    drawText(ctx, foot, new Rect(14, 151, 142, 12), Font.mediumSystemFont(9), GRAY, "left");
  }
  return ctx.getImage();
}
function finishWidget(img) {
  const w = new ListWidget();
  w.backgroundImage = updRing(img);
  w.addSpacer();
  w.url = URLScheme.forRunningScript();
  w.refreshAfterDate = new Date(Date.now() + 12 * 3600 * 1000);
  return w;
}
function errorWidget(msg) {
  const w = new ListWidget();
  const g = new LinearGradient();
  g.colors = [new Color("#2C2C2E"), new Color("#1C1C1E")];
  g.locations = [0, 1];
  w.backgroundGradient = g;
  const t = w.addText("Metro Migration");
  t.font = Font.semiboldSystemFont(12);
  t.textColor = new Color("#FFFFFF");
  w.addSpacer(4);
  const m = w.addText(String(msg));
  m.font = Font.systemFont(10);
  m.textColor = new Color(GRAY);
  w.addSpacer();
  w.url = URLScheme.forRunningScript();
  w.refreshAfterDate = new Date(Date.now() + 3600 * 1000);
  return w;
}

// ---------- Sharing the full-screen view as a light, printable PDF ----------
