function rFmt(v) { return sgn(v) + Math.abs(v).toFixed(1); }
function money(v) { var a = Math.abs(v); return a >= 1e9 ? "$" + (a / 1e9).toFixed(1) + "B" : a >= 1e6 ? "$" + Math.round(a / 1e6) + "M" : "$" + Math.round(a / 1000) + "k"; }
function city(m) { return m.n.split(",")[0]; }
function popAt(m, year) { var i = D.popYears.indexOf(year); return i >= 0 ? m.pop[i] : null; }
function nYrs() { return range.b - range.a + 1; }
function periodHead() { var a = YRS[range.a], b = YRS[range.b]; return a === b ? "in the Year to July " + b : "From July " + (a - 1) + " to July " + b; }
function periodShort() { var a = YRS[range.a], b = YRS[range.b]; return a === b ? "July " + (b - 1) + " to July " + b : "July " + (a - 1) + " to July " + b + " (" + nYrs() + " years)"; }
