  var bs = el("metric").querySelectorAll("button");
  for (var i = 0; i < bs.length; i++) { bs[i].className = bs[i].getAttribute("data-k") === state.metric ? "on" : ""; bs[i].onclick = function () { state.metric = this.getAttribute("data-k"); renderBoard(); el("headline").textContent = headlineText(); }; }
  var rowsEl = document.querySelectorAll("#lbUp .lr, #lbDown .lr");
