    tile("Per 1,000 residents a year", g.rate != null ? rFmt(g.rate) : "–", row.rr ? "rank " + row.rr + " of " + cache.bigs.length + " metros of 1M+" : "metros under 1M aren't ranked", g.rate >= 0 ? GREEN : RED) +
    tile("International moves", kFmt(g.intl), "net, " + (nYrs() > 1 ? nYrs() + " years" : "1 year"), GOLD) +
    tile("Births minus deaths", kFmt(g.nat), "total change " + kFmt(g.chg), TEAL);
