  var X = function (i) { return L + slot * (i + 0.5); };
  var lo = 0, hi = 0;
  YRS.forEach(function (y, i) {
    var pos = 0, neg = 0;
    [m.dom[i], m.intl[i], m.nat[i]].forEach(function (v) { if (v == null) return; if (v > 0) pos += v; else neg += v; });
    hi = Math.max(hi, pos, m.chg[i] || 0); lo = Math.min(lo, neg, m.chg[i] || 0);
  });
  var st = niceStep((hi - lo) || 100); lo = Math.floor(lo / st) * st; hi = Math.ceil(hi / st) * st; if (hi === lo) hi = lo + st;
  var Y = function (v) { return B - (v - lo) / (hi - lo) * (B - T); };
  var s = '<rect x="' + (L + slot * range.a) + '" y="' + T + '" width="' + (slot * nYrs()) + '" height="' + (B - T) + '" fill="#2C2C2E"/>';
  for (var v = lo; v <= hi + st / 2; v += st) {
    s += '<line x1="' + L + '" x2="' + R + '" y1="' + Y(v) + '" y2="' + Y(v) + '" stroke="' + (Math.abs(v) < st / 1000 ? "#8E8E93" : "#3A3A3C") + '" stroke-width="1"/>';
    s += '<text x="' + (L - 5) + '" y="' + (Y(v) + 3.5) + '" font-size="10.5" text-anchor="end" fill="#8E8E93">' + axisK(v) + "</text>";
  }
  var bw = Math.max(3, slot * 0.66), pts = [];
